 if(kind==='league-lose'){title='次の一歩を、仲間と。';text='U-Speak parkで仲間全員の集中力を無料回復できます。仲間・経験値・コインは失いません。';cards=button('sanctuary','U-Speak parkで回復する','class="primary"')+button('team','チームを整える','class="primary"')+button('review','ことばを練習する')}
