 function microphone(){const q=battle?.q;if(!q||battle.locked)return;const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){$('#ad-mic-status').textContent='このブラウザは音声認識に対応していません。文字入力で同じ報酬を獲得できます。';return}stopSpeech();try{recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;recognition.maxAlternatives=3;const thisBattle=battle;$('#ad-mic-status').textContent='聞いています… '+q.meaning+' を英語で。';recognition.onresult=e=>{if(battle!==thisBattle||battle.locked)return;const texts=Array.from(e.results[0]).map(r=>r.transcript);const value=texts.find(x=>normalize(x)===normalize(q.word))||texts[0];$('#ad-typed').value=value;$('#ad-mic-status').textContent='認識結果：'+value+'。確認して「答える」を押してください。'};recognition.onerror=e=>{const status=$('#ad-mic-status');if(status)status.textContent=e.error==='not-allowed'?'マイクの許可がありません。文字入力で続けられます。':'音声を認識できませんでした。再試行か文字入力で続けられます。'};recognition.start()}catch{const status=$('#ad-mic-status');if(status)status.textContent='音声認識を開始できません。文字入力で続けられます。'}}
