 return {progress,magic,treasure,open,startCapture,answer,available,conditionLabel,cry,get sneaking(){return sneaking},get reduced(){return progress.settingsSnapshot().reduced},get view(){return view},isTab:name=>name==='sanctuary'||tabs.some(([id])=>id===name),entry:id=>progress.entry(id),onCapture:id=>progress.capture(id),onFlight:id=>{progress.flight(id);refreshHud()},onRegion:()=>refreshHud(),close:()=>{if(battle?.casting&&battle.castResult?.success)result('capture-win');stopSpeech();battle=null;state.busy=false;magic.close()},update(t,dt){magic.update(t,dt);treasure.update(t,dt);if(battle?.casting){battle.castTime+=dt;if(battle.castTime>=1.6){battle.casting=false;if(battle.castResult.success)result('capture-win');else{battle.castFailed=true;renderCapture();}}}if(state.mode==='show'){showTime+=dt;const reduced=progress.settingsSnapshot().reduced;showActors.forEach((g,i)=>{animateCreature(g,reduced?0:t,i,'happy');g.position.y=.3+(reduced?0:Math.abs(Math.sin(t*3+i))*.45);g.rotation.y=reduced?0:Math.sin(t*.8+i)*.5});ctx.camera.position.set(122+(reduced?0:Math.sin(showTime*.12)*7),5.8,38);ctx.camera.lookAt(122,1.5,26);player.visible=false;$('#rpg-flight-progress').style.width=Math.min(100,showTime/24*100)+'%';if(showTime>=24)finishShow()}sessionSeconds+=document.hidden?0:dt;timeBuffer+=document.hidden?0:dt;const settings=progress.settingsSnapshot();if(timeBuffer>30){progress.time(timeBuffer);timeBuffer=0}if(sessionSeconds>=settings.minutes*60&&!restNotice){restNotice=true;toast('今日のひと区切り。記録は保存されています。いつでも休憩してね。')}if(!firstPrompt&&t>.4&&!document.querySelector('dialog[open]')&&ctx.allowedUi()){firstPrompt=true;if(!progress.state.starter)open('journey')}if(t-lastTime>1.5){lastTime=t;refreshHud()}effects.set(weather,settings.reduced,settings.season);effects.update(t,dt,REGION_BY_ID[state.current],!state.insidePark&&!REGION_BY_ID[state.current].hub&&!state.busy);for(let i=0;i<guestModels.length;i++){const g=guestModels[i];g.visible=!state.busy||state.mode==='flight';if(state.mode==='flight'){g.position.copy(new THREE.Vector3((i-1)*.3,.5,.2).applyMatrix4(ctx.plane.matrixWorld));g.rotation.copy(ctx.plane.rotation)}else{g.position.lerp(player.position.clone().add(new THREE.Vector3(2+i*.8,.2,2+i)),.045);animateCreature(g,settings.reduced?0:t,i)}}},getSnapshot:()=>({view,battle: battle?{...battle}:null,weather,sneaking})};
